@startuml

class SensorController {
  + sensorData : float
  + querySensorValues() : float
  + login(username, password) : boolean
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class TemperatureSensor {
  + minRange : float
  + maxRange : float
}

class PowerSensor {
  + totalConsumption : float
}

class Room {
  + description : string
}

class Apartment {
  + address : string
}

class Inhabitant {
  + username : string
  + password : string
  + isAdmin : boolean
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {
  + checkThresholds()
  + sendAlert()
}

enum Unit {
  CELSIUS
  WATT
}

Sensor --|> TemperatureSensor
Sensor --|> PowerSensor

SensorController "1" *-- "*" Sensor
SensorController "1" *-- "1..*" Inhabitant
SensorController "1" *-- "1..*" Room
SensorController "1" *-- "1" Apartment

Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor

Inhabitant "1..*" -- "1..*" Apartment : inhabits
Inhabitant "0..*" -- "0..*" Sensor : configures

Sensor "1" -- "1" Room : assignedTo
Sensor "1" *-- "1..*" SensorValue : records
Sensor "1" o-- "1" SensorValue : lastValue

EMonitor ..> SensorController : attachedTo
EMonitor ..> Sensor : checksThresholds

@enduml

